SELECT 
FROM calibration_params cp



        AND cp.scope_type = #{scopeType}


        AND cp.scope_id = #{scopeId}


        AND cp.target_size_id = #{targetSizeId}


        AND cp.enabled = #{enabled}


        AND cp.status = #{status}


        AND cp.confidence_level = #{confidenceLevel}


        AND cp.version = #{version}


ORDER BY cp.update_time DESC, cp.create_time DESC, cp.param_id DESC

SELECT 
FROM calibration_params cp

WHERE cp.param_id = #{paramId}

SELECT COALESCE(MAX(version), 0)
FROM calibration_params

    scope_type = #{scopeType}

        AND scope_id IS NULL


        AND scope_id = #{scopeId}


        AND target_size_id IS NULL


        AND target_size_id = #{targetSizeId}

    AND calibration_type = #{calibrationType}

SELECT 
FROM calibration_params

    scope_type = #{scopeType}

        AND scope_id IS NULL


        AND scope_id = #{scopeId}


        AND target_size_id IS NULL


        AND target_size_id = #{targetSizeId}

    AND calibration_type = #{calibrationType}
    AND enabled = TRUE
    AND effective_from <= #{now}
    AND (effective_until IS NULL OR effective_until >= #{now})

ORDER BY version DESC, param_id DESC

SELECT rl.log_id, rl.school_id, COALESCE(ss.school_name, CONCAT('学校#', rl.school_id), '未关联学校') AS school_name, rl.uniform_id, COALESCE(su.name, CONCAT('商品#', rl.uniform_id), '未关联商品') AS uniform_name, rl.recommended_size_id, rl.recommended_size_name, rl.calibration_details, rl.create_time FROM recommendation_log rl LEFT JOIN s_schools ss ON ss.school_id = rl.school_id LEFT JOIN s_uniform su ON su.id = rl.uniform_id
rl.calibration_details IS NOT NULL AND rl.calibration_details != ''
AND rl.school_id = #{schoolId}
AND rl.uniform_id = #{uniformId}
AND rl.create_time >= #{startTime}
AND rl.create_time <= #{endTime}
AND rl.calibration_details LIKE CONCAT('%\"paramId\":', #{paramId}, '%')
AND rl.calibration_details LIKE CONCAT('%\"version\":', #{version}, '%')
ORDER BY rl.create_time DESC, rl.log_id DESC LIMIT #{limit}
